package com.sharehope.donation.controller;import com.sharehope.donation.dto.*;import com.sharehope.donation.model.Donation;import com.sharehope.donation.repository.DonationRepository;import com.sharehope.notification.NotificationService;import jakarta.validation.Valid;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController public class DonationController{private final DonationRepository repo;private final String secret;private final NotificationService notifications;DonationController(DonationRepository r,@Value("${app.payment.internal-secret:}")String s,NotificationService n){repo=r;secret=s;notifications=n;}
@PostMapping("/api/public/payment-events")public ResponseEntity<?> record(@RequestHeader(value="X-Payment-Secret",required=false)String supplied,@Valid @RequestBody DonationRecordRequest r){if(secret.isBlank()||!secret.equals(supplied))return ResponseEntity.status(401).build();boolean created=repo.findByProviderReference(r.providerReference()).isEmpty();Donation d=repo.findByProviderReference(r.providerReference()).orElseGet(()->Donation.builder().providerReference(r.providerReference()).build());d.setProvider(r.provider());d.setDonorName(r.donorName());d.setDonorEmail(r.donorEmail());d.setDonorPhone(r.donorPhone());d.setAmountCents(r.amountCents());d.setCurrency(r.currency().toUpperCase());d.setFrequency(r.frequency());d.setDesignation(r.designation());d.setStatus(r.status());if(r.receiptUrl()!=null&&!r.receiptUrl().isBlank())d.setReceiptUrl(r.receiptUrl());d=repo.save(d);if(created){notifications.sendAdminAlert("New ShareHope donation","/en/admin/donations");if("Succeeded".equalsIgnoreCase(d.getStatus()))notifications.sendDonationConfirmation(d);}return ResponseEntity.ok(d);}
@PatchMapping("/api/public/payment-events/{reference}")public ResponseEntity<?> status(@RequestHeader(value="X-Payment-Secret",required=false)String supplied,@PathVariable String reference,@RequestBody Map<String,String> body){if(secret.isBlank()||!secret.equals(supplied))return ResponseEntity.status(401).build();return repo.findByProviderReference(reference).map(d->{d.setStatus(body.getOrDefault("status",d.getStatus()));return ResponseEntity.ok(repo.save(d));}).orElseGet(()->ResponseEntity.notFound().build());}
@GetMapping("/api/admin/donations")public List<Donation> list(){return repo.findAllByOrderByCreatedAtDesc();}}
